static const size_t NUM_TEST_PARTS = sizeof(TEST_PARTS) / sizeof(TEST_PARTS[0]);

// Number of iterations for averaging
#define NUM_ITERATIONS 1

/**
 * Benchmark esp32_bc-ur decoder
 * Returns: average decode time in microseconds, or -1 on failure
 * fragments_used: output parameter for number of fragments used to complete
 */
static int64_t benchmark_esp32_bcur(size_t *fragments_used)
{
    int64_t total_time = 0;
    size_t total_fragments = 0;

    for (int iter = 0; iter < NUM_ITERATIONS; ++iter) {
        // Create decoder using placement (more efficient, as used in production)
        uint8_t decoder[URDECODER_SIZE];
        urcreate_placement_decoder(decoder, sizeof(decoder));

        const int64_t start = esp_timer_get_time();

        // Feed all parts
        size_t parts_used = 0;
        for (size_t i = 0; i < NUM_TEST_PARTS; ++i) {
            if (!urreceive_part_decoder(decoder, TEST_PARTS[i])) {
                JADE_LOGE("esp32_bc-ur: Failed to receive part %u", (unsigned int)i);
                urfree_placement_decoder(decoder);
                return -1;
            }
            parts_used++;

            if (uris_complete_decoder(decoder)) {
                break;
            }
        }

        const int64_t end = esp_timer_get_time();

        // Verify success
        if (!uris_success_decoder(decoder)) {
            JADE_LOGE("esp32_bc-ur: Decoding failed");
            urfree_placement_decoder(decoder);
            return -1;
        }

        // Verify we got a result
        uint8_t* result = NULL;
        size_t result_len = 0;
        const char* type = NULL;
        urresult_ur_decoder(decoder, &result, &result_len, &type);

        if (!result || result_len == 0 || !type) {
            JADE_LOGE("esp32_bc-ur: Invalid result");
            urfree_placement_decoder(decoder);
            return -1;
        }

        urfree_placement_decoder(decoder);
        total_time += (end - start);
        total_fragments += parts_used;
    }

    if (fragments_used) {
        *fragments_used = total_fragments / NUM_ITERATIONS;
    }
    return total_time / NUM_ITERATIONS;
}

/**
 * Benchmark cUR decoder
 * Returns: average decode time in microseconds, or -1 on failure
 * fragments_used: output parameter for number of fragments used to complete
 */
static int64_t benchmark_cur(size_t *fragments_used)
{
    int64_t total_time = 0;
    size_t total_fragments = 0;

    for (int iter = 0; iter < NUM_ITERATIONS; ++iter) {
        // Create decoder
        ur_decoder_t* decoder = ur_decoder_new();
        if (!decoder) {
            JADE_LOGE("cUR: Failed to create decoder");
            return -1;
        }

        const int64_t start = esp_timer_get_time();

        // Feed all parts
        size_t parts_used = 0;
        for (size_t i = 0; i < NUM_TEST_PARTS; ++i) {
            if (!ur_decoder_receive_part(decoder, TEST_PARTS[i])) {
                JADE_LOGE("cUR: Failed to receive part %u (error: %d)", (unsigned int)i, ur_decoder_get_last_error(decoder));
                ur_decoder_free(decoder);
                return -1;
            }
            parts_used++;

            if (ur_decoder_is_complete(decoder)) {
                break;
            }
        }

        const int64_t end = esp_timer_get_time();

        // Verify success
        if (!ur_decoder_is_success(decoder)) {
            JADE_LOGE("cUR: Decoding failed (error: %d)", ur_decoder_get_last_error(decoder));
            ur_decoder_free(decoder);
            return -1;
        }

        // Verify we got a result
        ur_result_t* result = ur_decoder_get_result(decoder);
        if (!result || !result->cbor_data || result->cbor_len == 0 || !result->type) {
            JADE_LOGE("cUR: Invalid result");
            ur_decoder_free(decoder);
            return -1;
        }

        ur_decoder_free(decoder);
        total_time += (end - start);
        total_fragments += parts_used;
    }

    if (fragments_used) {
        *fragments_used = total_fragments / NUM_ITERATIONS;
    }
    return total_time / NUM_ITERATIONS;
}

/**
 * Compare decoded results between the two libraries
 * Returns true if both produce identical results
 */
static bool compare_results(void)
{
    // Decode with esp32_bc-ur
    uint8_t bcur_decoder[URDECODER_SIZE];
    urcreate_placement_decoder(bcur_decoder, sizeof(bcur_decoder));

    for (size_t i = 0; i < NUM_TEST_PARTS; ++i) {
        urreceive_part_decoder(bcur_decoder, TEST_PARTS[i]);
        if (uris_complete_decoder(bcur_decoder)) {
            break;
        }
    }

    uint8_t* bcur_result = NULL;
    size_t bcur_result_len = 0;
    const char* bcur_type = NULL;
    urresult_ur_decoder(bcur_decoder, &bcur_result, &bcur_result_len, &bcur_type);

    // Decode with cUR
    ur_decoder_t* cur_decoder = ur_decoder_new();
    if (!cur_decoder) {
        urfree_placement_decoder(bcur_decoder);
        return false;
    }

    for (size_t i = 0; i < NUM_TEST_PARTS; ++i) {
        ur_decoder_receive_part(cur_decoder, TEST_PARTS[i]);
        if (ur_decoder_is_complete(cur_decoder)) {
            break;
        }
    }

    ur_result_t* cur_result = ur_decoder_get_result(cur_decoder);

    // Compare results
    bool match = true;

    if (!bcur_result || !cur_result) {
        JADE_LOGE("One or both decoders failed to produce a result");
        match = false;
    } else {
        // Compare types
        if (strcmp(bcur_type, cur_result->type) != 0) {
            JADE_LOGE("Type mismatch: esp32_bc-ur='%s', cUR='%s'", bcur_type, cur_result->type);
            match = false;
        }

        // Compare lengths
        if (bcur_result_len != cur_result->cbor_len) {
            JADE_LOGE("Length mismatch: esp32_bc-ur=%u, cUR=%u", (unsigned int)bcur_result_len, (unsigned int)cur_result->cbor_len);
            match = false;
        }

        // Compare data
        if (match && memcmp(bcur_result, cur_result->cbor_data, bcur_result_len) != 0) {
            JADE_LOGE("Data mismatch between decoders");
            match = false;
        }
    }

    // Cleanup
    urfree_placement_decoder(bcur_decoder);
    ur_decoder_free(cur_decoder);

    return match;
}

/**
 * Run the UR decoder benchmark
 */
void run_ur_benchmark(void)
{
    JADE_LOGI("=== UR Decoder Benchmark ===");
    JADE_LOGI("Test vector: %u parts (crypto-psbt)", (unsigned int)NUM_TEST_PARTS);
    JADE_LOGI("Iterations: %d", NUM_ITERATIONS);
    JADE_LOGI("");

    // First verify both decoders produce the same result
    JADE_LOGI("Verifying result consistency...");
    if (!compare_results()) {
        JADE_LOGE("FAILED: Decoders produce different results!");
        return;
    }
    JADE_LOGI("PASSED: Both decoders produce identical results");
    JADE_LOGI("");

    // Benchmark esp32_bc-ur
    JADE_LOGI("Benchmarking esp32_bc-ur...");
    size_t bcur_fragments = 0;
    const int64_t bcur_time = benchmark_esp32_bcur(&bcur_fragments);
    if (bcur_time < 0) {
        JADE_LOGE("esp32_bc-ur benchmark failed");
        return;
    }
    JADE_LOGI("esp32_bc-ur average: %ld us (%u fragments)", (long)bcur_time, (unsigned int)bcur_fragments);

    // Benchmark cUR
    JADE_LOGI("Benchmarking cUR...");
    size_t cur_fragments = 0;
    const int64_t cur_time = benchmark_cur(&cur_fragments);
    if (cur_time < 0) {
        JADE_LOGE("cUR benchmark failed");
        return;
    }
    JADE_LOGI("cUR average: %ld us (%u fragments)", (long)cur_time, (unsigned int)cur_fragments);

    // Print comparison
    JADE_LOGI("");
    JADE_LOGI("=== Results ===");
    JADE_LOGI("esp32_bc-ur: %ld us (%u fragments)", (long)bcur_time, (unsigned int)bcur_fragments);
    JADE_LOGI("cUR:         %ld us (%u fragments)", (long)cur_time, (unsigned int)cur_fragments);

    if (cur_time < bcur_time) {
        const double speedup = (double)bcur_time / (double)cur_time;
        JADE_LOGI("cUR is %.2fx faster", speedup);
    } else if (bcur_time < cur_time) {
        const double speedup = (double)cur_time / (double)bcur_time;
        JADE_LOGI("esp32_bc-ur is %.2fx faster", speedup);
    } else {
        JADE_LOGI("Both have equal performance");
    }
}
